You're looking to tell the TypeScript type system about a value that could potentially have multiple types, but in practice, you know it will only have one. This is known as a "discriminated union" or "tagged union."

One way to achieve this is by using a type guard. A type guard is a function that narrows the type of a value within a specific scope. Here's an example:

```typescript
type Shape =
  | { type: 'circle'; radius: number }
  | { type:'square'; side: number };

function isCircle(shape: Shape): shape is { type: 'circle'; radius: number } {
  return shape.type === 'circle';
}

function isSquare(shape: Shape): shape is { type:'square'; side: number } {
  return shape.type ==='square';
}

const shape: Shape = { type: 'circle', radius: 5 };

if (isCircle(shape)) {
  // shape is now known to be { type: 'circle'; radius: number }
  console.log(shape.radius); // no error
} else if (isSquare(shape)) {
  // shape is now known to be { type:'square'; side: number }
  console.log(shape.side);

